-- ============================================================================
--  Gentegre AI — LOT BAKIYESI (depo bazinda) + GOCTEN GELEN MUTABAKAT
--  117_stok_lot_durum.sql
--
--  MUTABAKATIN KOKU: eski sistemde lot bakiyesi STOKIZLEME.KALAN'da DEGIL, ayri
--  bir tabloda (STOKIZLEMEDEPO: izlem x depo x adet) tutuluyordu ve bu tablo
--  goce HIC dahil edilmemisti. Elimizdeki KALAN alani ise "bu belge satirindan
--  henuz devredilmemis miktar" (donusid zinciri) anlamina geliyor - satis
--  faturasi satirinin bile kalani vardir. Bu yuzden lot kalanlari toplami depo
--  miktariyla tutmuyordu (2.459 stokta fark; or. stok 136: 1.766'ya karsi 84).
--
--  ESKI BELGE TURLERI (izlem satirlarindaki belge_tur):
--     2 devir · 3 giris fisi · 4 cikis fisi · 6 URETIM FISI (recete: hammadde
--     cikar, mamul girer - Utablo.UretimFisiOlusturSP, TUR=6) · 10/11/12 alis ·
--     14/15/16 satis · 20 transfer · 101 SATINALMA SIPARISI/TALEBI (SIPARIS
--     tablosu, TUR in 9/19/101/105 - stok hareketi YOK, taahhut) · 105 stoktan
--     talep · 109/119 konsinye.
--  101 ve 105 satirlarinin "kalan"i stokta mal DEGILDIR; 6'da ayni belge turu
--  hem girisi hem cikisi tasidigi icin yon satirdan anlasilamaz. Yani eldeki
--  veriyle dogru lot bakiyesi HESAPLANAMAZ - kaynaktan alinmasi gerekir.
--
--  COZUM: lot bakiyesi icin stok_durum'un lot karsiligi olan ayri bir tablo
--  (stok_lot_durum) acilir ve ESKI SISTEMDEN gelen bakiyelerle tohumlanir.
--  Bundan sonra belge kaydi bu tabloyu da gunceller (giris +, cikis -,
--  transfer - / +). stok_izleme kendi anlamiyla (hareket defteri + zincir)
--  KALIR; kalan alani stok bakiyesi olarak KULLANILMAZ.
--
--  Tohum verisi BILIM veritabanindan uretildi:
--    select i.STOKID, d.DEPOID, i.SERILOTID, sum(d.ADET)
--      from STOKIZLEMEDEPO d join STOKIZLEME i on i.ID = d.IZLEMID
--     where i.SERILOTID > 0 and d.DEPOID > 0
--     group by i.STOKID, d.DEPOID, i.SERILOTID having sum(d.ADET) <> 0;
--  9.452 satir. Sunucuda MSSQL yok, o yuzden degerler dosyaya GOMULU.
--
--  NOT: lot bakiyeleri stok_durum ile birebir TUTMAZ (or. stok 136: lot 69/1/7,
--  stok_durum 78/2/3/1). Fark eski sistemde de vardi: lot izlemi baslamadan
--  once giren mal ve izlem yazmayan hareketler stok bakiyesinde var, lotta yok.
--  Sayimla kapatilmasi gereken bir DEVIR farkidir; uydurma lot uretmiyoruz.
-- ============================================================================
\set ON_ERROR_STOP on

create table if not exists public.stok_lot_durum (
    stok_id     integer not null references public.stok(id),
    depo_id     integer not null references public.depo(id),
    seri_lot_id integer not null references public.stok_seri_lot(id),
    kalan       numeric(24,6) not null default 0,
    primary key (stok_id, depo_id, seri_lot_id)
);

comment on table public.stok_lot_durum is
  'Lot bakiyesi: stok x depo x lot (117). stok_durum''un lot kirilimi. Belge kaydi gunceller.';
comment on column public.stok_lot_durum.kalan is
  'O depoda o lottan kalan miktar. stok_izleme.kalan ile ILGISI YOK (o zincir devri).';

create index if not exists ix_stok_lot_durum_stok on public.stok_lot_durum (stok_id, depo_id)
    where kalan <> 0;

-- Tohum yalniz TABLO BOSKEN yuklenir: ikinci calismada uzerine yazip
--   aradaki belge hareketlerini SIFIRLAMAZ.
do $$
declare v_var integer; v_yuklendi integer; v_atlanan integer;
begin
    select count(*) into v_var from public.stok_lot_durum;
    if v_var > 0 then
        raise notice '117: stok_lot_durum dolu (% satir) - tohum ATLANDI', v_var;
        return;
    end if;

    create temporary table gecici_lot_tohum (stok_id int, depo_id int, seri_lot_id int, kalan numeric(24,6))
        on commit drop;


    -- 114'te birlestirilen mukerrer lotlar: tohum eski id'yi tasiyor olabilir,
    --   tutulan kayda cevrilir ve toplanir.
    select t.stok_id, t.depo_id,
           coalesce(y.tasindigi_id, t.seri_lot_id) as seri_lot_id,
           sum(t.kalan)
      from gecici_lot_tohum t
      left join public.stok_seri_lot_tekil_yedek_114 y on y.id = t.seri_lot_id
      join public.stok l on l.id = t.stok_id
      join public.depo d on d.id = t.depo_id
     where exists (select 1 from public.stok_seri_lot s
                    where s.id = coalesce(y.tasindigi_id, t.seri_lot_id))
     group by 1, 2, 3
    having sum(t.kalan) <> 0
    on conflict (stok_id, depo_id, seri_lot_id) do update set kalan = excluded.kalan;

    get diagnostics v_yuklendi = row_count;
    select count(*) into v_atlanan from gecici_lot_tohum t
      left join public.stok_seri_lot_tekil_yedek_114 y on y.id = t.seri_lot_id
     where not exists (select 1 from public.stok_seri_lot s
                        where s.id = coalesce(y.tasindigi_id, t.seri_lot_id))
        or not exists (select 1 from public.stok l where l.id = t.stok_id)
        or not exists (select 1 from public.depo d where d.id = t.depo_id);

    raise notice '117 tohum: % lot bakiyesi yuklendi, % satir atlandi (stok/depo/lot bulunamadi)',
                 v_yuklendi, v_atlanan;
end $$;

do $$
declare v_satir integer; v_stok integer; v_toplam numeric;
begin
    select count(*), count(distinct stok_id), sum(kalan) into v_satir, v_stok, v_toplam
      from public.stok_lot_durum where kalan > 0;
    raise notice '117 tamam: % lot bakiyesi satiri, % stok, toplam % birim',
                 v_satir, v_stok, round(v_toplam, 2);
end $$;
